  "Ich hab eine empfindliche Kopfhaut.": "Ho il cuoio capelluto sensibile.",
  "Wie hätten Sie es denn gern?": "E come li desidera?",
  "So wie immer, bitte.": "Come sempre, per favore.",
  "Ich möchte es heute glätten lassen.": "Oggi vorrei farmeli lisciare.",
  "Können Sie mir die Haare hochstecken? Ich geh auf eine Hochzeit.": "Mi può raccogliere i capelli? Vado a un matrimonio.",
  "Das Ergebnis gefällt mir richtig gut.": "Il risultato mi piace davvero molto.",
  "So lassen wir es, das steht Ihnen.": "Lasciamoli così, le stanno bene.",
  "Zum Nachschneiden komm ich in sechs Wochen wieder.": "Torno fra sei settimane per il ritocco.",
