  "Beschrifte jeden Karton, sonst suchen wir ewig.": "Scrivi su ogni scatolone, altrimenti cerchiamo per ore.",
  "Das Geschirr wickeln wir in Luftpolsterfolie.": "Le stoviglie le avvolgiamo nel pluriball.",
  "Der Transporter ist für Samstag gemietet.": "Il furgone è prenotato per sabato.",
