  "Kannst du beim Schleppen helfen? Ich bestelle Pizza für alle.": "Mi dai una mano a caricare? Offro la pizza a tutti.",
  "Vorsicht, die Kiste ist schwerer, als sie aussieht.": "Attento, la cassa pesa più di quanto sembri.",
  "Das Sofa passt nicht durchs Treppenhaus.": "Il divano non passa per le scale.",
  "Der Schrank wird abgebaut und drüben wieder aufgebaut.": "L'armadio si smonta e si rimonta di là.",
  "Lass uns zuerst das Bett aufbauen, der Rest kann warten.": "Montiamo prima il letto, il resto può aspettare.",
  "Wo soll das Regal hin?": "Dove va lo scaffale?",
  "Ich finde den Karton mit den Handtüchern nicht.": "Non trovo lo scatolone degli asciugamani.",
  "Der Umzugswagen muss bis achtzehn Uhr zurück.": "Il furgone del trasloco va riportato entro le diciotto.",
  "Nach dem Umzug tut mir alles weh.": "Dopo il trasloco mi fa male tutto.",
  "Wir müssen uns innerhalb von zwei Wochen ummelden.": "Dobbiamo cambiare la residenza entro due settimane.",
  "Hast du den Nachsendeauftrag schon gestellt?": "Hai già fatto la richiesta di rispedizione della posta?",
  "Denk daran, die Adresse bei der Bank zu ändern.": "Ricordati di cambiare l'indirizzo in banca.",
  "Strom und Internet sind schon angemeldet.": "La luce e internet sono già attivati.",
  "Die Kaution bekommen wir erst nach der Übergabe zurück.": "La caparra ce la ridanno solo dopo la consegna.",
  "Bei der Übergabe zählen wir die Schlüssel.": "Alla consegna contiamo le chiavi.",
  "Die alten Möbel kommen auf den Sperrmüll.": "I mobili vecchi vanno con i rifiuti ingombranti.",
  "Die Nachbarn haben sich schon vorgestellt.": "I vicini si sono già presentati.",
  "Zur Einweihungsfeier seid ihr herzlich eingeladen.": "Siete tutti invitati alla festa di inaugurazione.",
  "Endlich fühlt es sich wie zu Hause an.": "Finalmente sembra casa.",
  "Was machst du am Samstag? Wir ziehen um.": "Che fai sabato? Traslochiamo.",
  "Ich ahne, worauf das hinausläuft.": "Immagino già dove vuoi arrivare.",
  "Es gibt Pizza und Getränke für alle Helfer.": "C'è pizza e da bere per tutti quelli che danno una mano.",
  "Na gut. Aber ich trag keine Waschmaschine.": "Va bene. Ma io la lavatrice non la porto.",
  "Wohin mit dem großen Spiegel?": "Dove mettiamo lo specchio grande?",
