  "Bei Glatteis fahr ich lieber gar nicht erst los.": "Con il ghiaccio nero preferisco non partire proprio.",
  "Die Straßen sind spiegelglatt, fahr vorsichtig.": "Le strade sono uno specchio, guida piano.",
  "Zieh dich warm an, es hat über Nacht gefroren.": "Copriti bene, stanotte ha gelato.",
  "Der See ist zugefroren, aber das Eis trägt noch nicht.": "Il lago è ghiacciato, ma il ghiaccio non regge ancora.",
  "Das ist nur ein Schauer, der zieht gleich vorbei.": "È solo un acquazzone, passa subito.",
  "Stell dich kurz unter bis der Regen nachlässt.": "Mettiti al riparo un attimo finché la pioggia non cala.",
  "Ich bin komplett nass geworden.": "Mi sono bagnato completamente.",
  "Nimm lieber einen Schirm mit, es soll später regnen.": "Portati piuttosto l'ombrello, dicono che dopo piove.",
  "Es soll das ganze Wochenende durchregnen.": "Dicono che pioverà tutto il fine settimana.",
  "Ich bin in eine Pfütze getreten, meine Schuhe sind durch.": "Ho messo il piede in una pozzanghera, ho le scarpe fradice.",
  "Nach dem Regen klart es meistens schnell auf.": "Dopo la pioggia di solito schiarisce in fretta.",
  "Am Nachmittag sind Gewitter angesagt.": "Nel pomeriggio sono previsti temporali.",
  "Hast du den Donner gehört? Das war nah.": "Hai sentito il tuono? Era vicino.",
  "Bei Gewitter gehen wir vom Platz.": "Con il temporale usciamo dal campo.",
  "Es hat gehagelt, die Autos haben Dellen.": "Ha grandinato, le macchine sono ammaccate.",
  "Der Sturm hat Äste auf die Straße geweht.": "Il vento ha buttato rami sulla strada.",
  "Das Unwetter soll erst am Abend kommen.": "Il maltempo dovrebbe arrivare solo di sera.",
  "Bei der Hitze schlafe ich nachts kaum.": "Con questo caldo di notte non dormo quasi.",
  "Trink genug bei dem Wetter.": "Bevi abbastanza con questo tempo.",
  "Ich hab mir einen Sonnenbrand geholt.": "Mi sono preso una scottatura.",
  "Im Schatten ist es auszuhalten.": "All'ombra si sopporta.",
  "Drinnen ist es schön kühl, mach die Rollläden runter.": "Dentro si sta fresco, abbassa le tapparelle.",
  "Endlich eine Abkühlung nach der Hitzewelle.": "Finalmente un po' di fresco dopo l'ondata di caldo.",
  "Morgen soll es endlich abkühlen.": "Domani finalmente dovrebbe rinfrescare.",
  "Wollen wir das Grillen lieber verschieben?": "Rimandiamo il barbecue?",
  "Bei dem Nebel sieht man keine fünfzig Meter.": "Con questa nebbia non si vedono cinquanta metri.",
  "Der Wetterbericht lag mal wieder daneben.": "Le previsioni hanno sbagliato un'altra volta.",
  "Für Samstag sind Gewitter angesagt.": "Per sabato danno temporali.",
  "Ausgerechnet zum Grillen.": "Proprio il giorno del barbecue.",
  "Wollen wir lieber auf Sonntag verschieben?": "Lo spostiamo a domenica?",
  "Ja, da soll es trocken bleiben.": "Sì, quel giorno dovrebbe restare asciutto.",
  "Fährst du heute mit dem Auto zur Arbeit?": "Vai al lavoro in macchina oggi?",
  "Bei dem Glatteis? Lieber nicht.": "Con questo ghiaccio? Meglio di no.",
  "Die Bahn fährt aber auch nur unregelmäßig.": "Ma anche il treno va a singhiozzo.",
