  "Kann ich ein Probetraining machen?": "Posso fare una lezione di prova?",
  "Was kostet die Mitgliedschaft im Monat?": "Quanto costa l'abbonamento al mese?",
  "Gibt es eine Mindestlaufzeit beim Vertrag?": "C'è una durata minima nel contratto?",
  "Denk an die Kündigungsfrist, sonst verlängert sich der Vertrag automatisch.": "Occhio al preavviso, altrimenti il contratto si rinnova da solo.",
  "Ich will erst mal reinschnuppern.": "Prima voglio dare un'occhiata.",
  "Der Mitgliedsbeitrag wird jährlich abgebucht.": "La quota associativa viene addebitata una volta all'anno.",
  "Ich hab meine Mitgliedschaft zum Jahresende gekündigt.": "Ho disdetto l'abbonamento per fine anno.",
  "Wärm dich erst auf bevor du an die Gewichte gehst.": "Scaldati prima di metterti ai pesi.",
  "Ist das Gerät noch frei?": "È libero questo attrezzo?",
  "Ich mach noch zwei Sätze, dann kannst du.": "Faccio ancora due serie, poi è tuo.",
  "Kannst du mir zeigen, wie das Gerät funktioniert?": "Mi fai vedere come funziona questo attrezzo?",
  "Nicht so viel Gewicht am Anfang, sonst hast du morgen Muskelkater.": "Non mettere troppo peso all'inizio, domani avrai i dolori.",
  "Nach dem Training dehne ich mich immer kurz.": "Dopo l'allenamento mi allungo sempre un po'.",
  "Die Umkleide ist heute wieder voll.": "Oggi lo spogliatoio è di nuovo pieno.",
  "Das Laufband neben mir ist gerade frei geworden.": "Il tapis roulant accanto a me si è appena liberato.",
  "Der Kurs ist leider schon ausgebucht.": "Il corso purtroppo è già al completo.",
  "Trag dich auf die Warteliste ein, es springt oft jemand ab.": "Mettiti in lista d'attesa, spesso qualcuno rinuncia.",
  "Der Rückenkurs tut mir richtig gut.": "Il corso per la schiena mi fa proprio bene.",
  "Der Anfängerkurs startet immer im September.": "Il corso per principianti parte sempre a settembre.",
  "Das Training ist dienstags um sieben.": "L'allenamento è il martedì alle sette.",
