  "Beim Vereinsfest helfen alle mit.": "Alla festa dell'associazione diamo tutti una mano.",
  "Ich geh montags und donnerstags zum Sport.": "Faccio sport il lunedì e il giovedì.",
  "Ich hab seit Jahren keinen Sport gemacht.": "Sono anni che non faccio sport.",
  "Fang langsam an und steigere dich.": "Comincia piano e aumenta pian piano.",
  "Nach drei Wochen merkt man schon einen Unterschied.": "Dopo tre settimane si nota già la differenza.",
  "Ich bin nach zwei Stockwerken völlig außer Atem.": "Dopo due piani sono completamente senza fiato.",
  "Hauptsache, du bleibst dran.": "L'importante è che tu non molli.",
  "Ich würde gern ein Probetraining vereinbaren.": "Vorrei fissare una lezione di prova.",
